import type { IQuoteLine, QuoteAcceptanceMethodEnum, QuoteStatusEnum } from '@shared/domain-types';

/** the stored fields of an Aldaron `Quote`; every amount is an integer in the smallest unit of `currency` */
export interface IQuoteAttributes {
  // `AL-2026-001`: generated by the server on creation, never typed
  number: string;
  client: Parse.Object;
  title: string;
  status: QuoteStatusEnum;
  lines: IQuoteLine[];
  // ISO 4217 code, one of `QUOTE_CURRENCIES`
  currency: string;
  // VAT in percent; unset means no VAT
  taxRate?: number;
  // computed by the server from `lines` and `taxRate` on every save
  totalAmount: number;
  // sum of the paid payments, kept by the payments once they exist; 0 until then
  paidAmount: number;
  // set the first time the quote is sent
  issuedAt?: Date;
  validUntil?: Date;
  // terms shown to the client
  notes?: string;
  // 1 for a first quote; a revision of the same number raises it
  version: number;
  acceptedAt?: Date;
  acceptanceMethod?: QuoteAcceptanceMethodEnum;
  createdBy?: Parse.User;
  updatedBy?: Parse.User;
}

/** what the back-office may write on a draft quote: everything else is computed or moved by the server */
export type QuoteInput = Pick<IQuoteAttributes, 'title' | 'lines' | 'currency'> & {
  // the id of the client
  client: string;
  taxRate: number | null;
  validUntil: Date | null;
  notes: string | null;
};

/** a named counter, such as the row incremented to number the quotes of one year */
export interface ICounterAttributes {
  // `quote-2026`
  name: string;
  value: number;
}
